package readcue

import (
        "os"
        "strings"
)

type Rec struct {
        Id  string
        Tok string
}

func Scan(path string) ([]Rec, error) {
        body, err := os.ReadFile(path)
        if err != nil {
                return nil, err
        }
        var out []Rec
        for _, line := range strings.Split(string(body), "\n") {
                line = strings.TrimSpace(line)
                if line == "" {
                        continue
                }
                id, tok, ok := strings.Cut(line, " ")
                if !ok {
                        continue
                }
                out = append(out, Rec{Id: strings.TrimSpace(id), Tok: strings.TrimSpace(tok)})
        }
        return out, nil
}
--- netsrc/tie.go ---
package netsrc

type Net struct {
        Par map[string]string
        Sz  map[string]int
}

func NewNet() *Net {
        return &Net{Par: map[string]string{}, Sz: map[string]int{}}
}

func (n *Net) Add(k string) {
        if _, ok := n.Par[k]; ok {
                return
        }
        n.Par[k] = k
        n.Sz[k] = 1
}

func (n *Net) Find(k string) string {
        n.Add(k)
        for n.Par[k] != k {
                n.Par[k] = n.Par[n.Par[k]]
                k = n.Par[k]
        }
        return k
}

func (n *Net) Join(a, b string) {
        ra, rb := n.Find(a), n.Find(b)
        if ra == rb {
                return
        }
        if n.Sz[ra] < n.Sz[rb] {
                ra, rb = rb, ra
        }
        n.Par[rb] = ra
        n.Sz[ra] += n.Sz[rb]
}

func OpTie(toks []string) *Net {
        n := NewNet()
        for _, t := range toks {
                n.Add(t)
        }
        return n
}

func OpMark(n *Net, tok string) string {
        return n.Find(tok)
}
